{
  "summary": "Start by constructing a table to calculate the sum of accepted and attempts for each lane's latest revision, filtering out retired lanes.",
  "actions": [
    {
      "tool": "construct_table",
      "name": "table.json",
      "schema": {
        "events": {
          "lane": "TEXT",
          "revision": "INTEGER",
          "state": "TEXT",
          "accepted": "INTEGER",
          "attempts": "INTEGER"
        }
      },
      "sql": "SELECT ledger.lane, ledger.revision, ledger.state, SUM(ledger.accepted) AS accepted, SUM(ledger.attempts) AS attempts FROM ledger WHERE ledger.state = 'active' GROUP BY ledger.lane, ledger.revision ORDER BY ledger.lane;"
    }
  ],
  "done": false
}
